        background: var(--surface);
        backdrop-filter: blur(20px);
        box-shadow: var(--shadow);
      }

      .preview-frame {
        padding: 1rem;
      }

      .preview-image {
        position: relative;
        overflow: hidden;
        border-radius: calc(var(--radius-xl) - 10px);
        background: linear-gradient(135deg, #dbeafe, #c4b5fd);
        min-height: 100%;
      }

      .preview-image::after {
        content: "";
        position: absolute;
        inset: 0;
        background: linear-gradient(180deg, rgba(15, 23, 42, 0) 40%, rgba(15, 23, 42, 0.18) 100%);
