        left: 1rem;
        bottom: 1rem;
        z-index: 1;
        padding: 0.45rem 0.75rem;
        border-radius: 999px;
        color: #fff;
        background: rgba(15, 23, 42, 0.54);
        backdrop-filter: blur(10px);
        font-size: 0.9rem;
      }

      .details-panel {
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        gap: 1.25rem;
        padding: 1.6rem;
      }

      .eyebrow {
        margin: 0 0 0.55rem;
        color: var(--accent);
        font-size: 0.82rem;
        font-weight: 700;
        letter-spacing: 0.14em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 4vw, 3.4rem);
        line-height: 1.04;
        letter-spacing: -0.05em;
      }

      .description {
        margin: 0.95rem 0 0;
        color: var(--muted);
        font-size: 1.02rem;
        max-width: 40ch;
      }

      .meta-grid {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 0.85rem;
        margin: 0;
      }

      .meta-item {
        padding: 0.95rem 1rem;
        border: 1px solid var(--line);
        border-radius: var(--radius-md);
        background: rgba(255, 255, 255, 0.65);
      }

      .meta-item dt {
        color: var(--muted);
        font-size: 0.86rem;
      }

      .meta-item dd {
        margin: 0.2rem 0 0;
        font-weight: 600;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        align-items: center;
      }

      .trigger,
      .secondary,
      .danger {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-height: 2.85rem;
        padding: 0.8rem 1.1rem;
        border: 1px solid transparent;
        border-radius: 999px;
        cursor: pointer;
        transition:
          transform 160ms ease,
          box-shadow 160ms ease,
          background-color 160ms ease,
          border-color 160ms ease;
      }

      .trigger {
        color: #fff;
        background: linear-gradient(135deg, var(--danger), #ef4444);
        box-shadow: 0 18px 30px rgba(220, 38, 38, 0.24);
      }

      .trigger:hover {
        transform: translateY(-1px);
      }

      .secondary {
        color: var(--text);
        border-color: var(--line);
        background: rgba(255, 255, 255, 0.75);
      }

      .trigger:focus-visible,
      .secondary:focus-visible,
      .danger:focus-visible,
      .dialog-close:focus-visible {
        outline: 3px solid rgba(37, 99, 235, 0.35);
        outline-offset: 2px;
      }

      .dialog-close {
        position: absolute;
        top: 1rem;
        right: 1rem;
        width: 2.5rem;
        height: 2.5rem;
        border: 1px solid var(--line);
        border-radius: 999px;
        color: var(--muted);
        background: rgba(255, 255, 255, 0.9);
        cursor: pointer;
      }

      dialog {
        width: min(92vw, 30rem);
        padding: 0;
        border: 1px solid rgba(148, 163, 184, 0.35);
        border-radius: 1.4rem;
        background: var(--surface-strong);
        color: var(--text);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgba(15, 23, 42, 0.55);
        backdrop-filter: blur(6px);
      }

      .dialog-panel {
        position: relative;
        padding: 1.4rem;
      }

      .dialog-kicker {
        margin: 0 0 0.4rem;
        color: var(--danger);
        font-size: 0.82rem;
        font-weight: 700;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      .dialog-title {
        margin: 0;
        padding-right: 2.5rem;
        font-size: 1.45rem;
        line-height: 1.15;
        letter-spacing: -0.04em;
      }

      .dialog-copy {
        margin: 0.75rem 0 0;
        color: var(--muted);
      }

      .dialog-actions {
        display: flex;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-top: 1.4rem;
      }

      .danger {
        color: #fff;
        background: linear-gradient(135deg, var(--danger-strong), var(--danger));
