        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      }

      .status {
        min-height: 1.5rem;
        margin-top: 1rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      @media (max-width: 860px) {
        .hero {
          grid-template-columns: 1fr;
        }

        .preview-image img {
          aspect-ratio: 16 / 10;
        }
      }

      @media (max-width: 560px) {
        .page-shell {
          width: min(100% - 1rem, 100%);
          padding-top: 0.75rem;
        }

        .topbar {
          border-radius: 1.3rem;
          padding: 0.9rem 1rem;
          align-items: flex-start;
          flex-direction: column;
        }

        .details-panel,
        .preview-frame {
          border-radius: 1.4rem;
        }

        .meta-grid {
          grid-template-columns: 1fr;
        }

        .dialog-actions {
          flex-direction: column-reverse;
        }

        .dialog-actions .secondary,
        .dialog-actions .danger {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: reduce) {
