          scroll-behavior: auto;
        }

        *,
        *::before,
        *::after {
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
          transition-duration: 0.01ms !important;
          scroll-behavior: auto !important;
        }
      }

      @media (forced-colors: active) {
        :root {
          --surface: Canvas;
          --surface-strong: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --line: CanvasText;
        }

        .topbar,
        .preview-frame,
        .details-panel,
        dialog,
        .meta-item {
          forced-color-adjust: auto;
          border-color: CanvasText;
        }

        .trigger,
        .danger,
        .secondary,
        .dialog-close {
          border-color: ButtonText;
          background: ButtonFace;
          color: ButtonText;
          box-shadow: none;
        }

        dialog::backdrop {
          background: rgba(0, 0, 0, 0.65);
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="app"></div>
    <script type="module">
      const App = () => `
        <div class="page-shell">
          <header class="topbar">
            <div class="brand" aria-label="Northstar library">
              <span class="brand-mark" aria-hidden="true">N</span>
              <span>Northstar Library</span>
            </div>
            <div class="topbar-note">Image preview</div>
          </header>

          <main id="main" tabindex="-1">
            <section class="hero" aria-labelledby="page-title">
              <div class="preview-frame">
                <div class="preview-image">
                  <img
                    src="https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1400&q=80"
                    alt="Snowy mountains surrounding a deep blue alpine lake at sunrise"
                  />
                  <span class="image-badge">4.8 MB · JPEG</span>
                </div>
              </div>

              <div class="details-panel">
                <div>
                  <p class="eyebrow">Library asset</p>
                  <h1 id="page-title">Alpine lake at sunrise</h1>
                  <p class="description">
                    Review this image before keeping it in your library. Use the delete action below to
                    open a confirmation dialog.
                  </p>
                </div>

                <dl class="meta-grid">
                  <div class="meta-item">
                    <dt>Uploaded</dt>
                    <dd>May 4, 2026</dd>
                  </div>
                  <div class="meta-item">
                    <dt>Source</dt>
                    <dd>Shared folder</dd>
                  </div>
                  <div class="meta-item">
                    <dt>Format</dt>
                    <dd>JPEG</dd>
                  </div>
                  <div class="meta-item">
                    <dt>Location</dt>
                    <dd>Dolomites</dd>
                  </div>
                </dl>

                <div>
                  <div class="actions" aria-label="Image actions">
                    <button type="button" class="trigger">Delete image</button>
                    <button type="button" class="secondary">Download</button>
                  </div>
                  <p class="status" id="status" aria-live="polite"></p>
                </div>
              </div>
            </section>
          </main>
        </div>

        <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-copy">
          <div class="dialog-panel">
            <button type="button" class="dialog-close" data-close aria-label="Close dialog">×</button>
            <p class="dialog-kicker">Confirm delete</p>
            <h2 class="dialog-title" id="delete-title">Delete this image from your library?</h2>
            <p class="dialog-copy" id="delete-copy">
              This will remove the image from your library. You can&apos;t undo this action.
            </p>

            <form method="dialog">
              <div class="dialog-actions">
                <button type="submit" value="cancel" class="secondary">Cancel</button>
                <button type="submit" value="delete" class="danger">Delete image</button>
              </div>
            </form>
          </div>
        </dialog>
      `;

      const root = document.getElementById("app");
      root.innerHTML = App();

      const dialog = document.getElementById("delete-dialog");
      const trigger = document.querySelector(".trigger");
      const closeButton = dialog.querySelector("[data-close]");
      const status = document.getElementById("status");

      trigger.addEventListener("click", () => {
        dialog.showModal();
      });

      closeButton.addEventListener("click", () => {
        dialog.close("cancel");
      });

      dialog.addEventListener("close", () => {
        if (dialog.returnValue === "delete") {
          status.textContent = "Image deleted from your library.";
        }
      });
    </script>
  </body>
</html>
